import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """

    # Check if a is less than 100
    if a < 100:
        # Check if a is a prime number
        if is_prime(a):
            return False

        # Find all prime factors of a
        prime_factors = prime_factors_of(a)

        # Check if there are exactly 3 prime factors
        if len(prime_factors) == 3:
            return True

        # Check if the product of the 3 smallest prime factors is equal to a
        if len(prime_factors) >= 3:
            product = 1
            for i in range(3):
                product *= prime_factors[i]
            return product == a

    return False


def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = math.isqrt(n)
    for i in range(3, sqrt_n + 1, 2):
        if n % i == 0:
            return False
    return True


def prime_factors_of(n):
    """Find all prime factors of a number."""
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors
